    r1->righttop.y=r1->lefttop.y;
    r2->leftbot.x=r2->lefttop.x;
    r2->leftbot.y=r2->rightbot.y;
    r2->righttop.x=r2->rightbot.x;
    r2->righttop.y=r2->lefttop.y;
